import csv

# Verify takeoff quantities match locations sum
takeoff_qty = {}
with open('output/takeoff.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        takeoff_qty[row['type_mark']] = int(row['quantity'])

loc_qty = {}
with open('output/locations.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        tm = row['type_mark']
        loc_qty[tm] = loc_qty.get(tm, 0) + int(row['count'])

print("Quantity verification (takeoff vs locations sum):")
all_match = True
for tm in sorted(set(takeoff_qty.keys()) | set(loc_qty.keys())):
    t = takeoff_qty.get(tm, 0)
    l = loc_qty.get(tm, 0)
    status = "OK" if t == l else "MISMATCH"
    if t != l:
        all_match = False
    print(f"  {tm}: takeoff={t}, locations={l} {status}")

# Verify BOM attribution rows match locations condition splits
bom_attr_qty = {}
with open('output/bom.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['for_type_mark'] != '(PURCHASE)':
            key = (row['for_type_mark'], row['condition'])
            bom_attr_qty[key] = bom_attr_qty.get(key, 0) + int(row['quantity'])

loc_cond_qty = {}
with open('output/locations.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        key = (row['type_mark'], row['condition'])
        loc_cond_qty[key] = loc_cond_qty.get(key, 0) + int(row['count'])

print("\nCondition split verification (locations vs BOM attribution):")
# Note: BOM attribution qty = device_count * multiplicity, so won't match directly
# Just verify all type/condition pairs in locations have BOM entries
missing = []
for key in loc_cond_qty:
    if key not in bom_attr_qty:
        missing.append(key)
if missing:
    print(f"  Missing BOM entries for: {missing}")
else:
    print("  All type/condition pairs from locations have BOM attribution rows")

print("\nAll verifications complete.")
